def distancia_edicion(a: str, b: str) -> int:
    """
    Devuelve la distancia de Levenshtein entre dos cadenas.

    Operaciones permitidas:
    - Inserción de un carácter
    - Borrado de un carácter
    - Sustitución de un carácter

    Cada operación cuesta 1.
    """
    if a == b:
        return 0

    if not a:
        return len(b)

    if not b:
        return len(a)

    # Optimización de memoria: solo se necesita una fila del DP
    dp = list(range(len(b) + 1))

    for i, ca in enumerate(a, start=1):
        prev = dp[0]
        dp[0] = i

        for j, cb in enumerate(b, start=1):
            temp = dp[j]

            if ca == cb:
                dp[j] = prev
            else:
                dp[j] = 1 + min(
                    prev,       # sustitución
                    dp[j],      # borrado
                    dp[j - 1]   # inserción
                )

            prev = temp

    return dp[-1]

def fusionar(intervalos):
    ordenados = sorted((min(a, b), max(a, b)) for a, b in intervalos)

    if not ordenados:
        return []

    resultado = []

    for inicio, fin in ordenados:
        if not resultado or inicio > resultado[-1][1]:
            resultado.append((inicio, fin))
        elif fin > resultado[-1][1]:
            resultado[-1] = (resultado[-1][0], fin)

    return resultado

def palindromo_mas_largo(s):
    if not s:
        return ""

    best_start = 0
    best_len = 1

    def expand(left, right):
        while left >= 0 and right < len(s) and s[left] == s[right]:
            left -= 1
            right += 1
        return left + 1, right - left - 1

    for i in range(len(s)):
        start, length = expand(i, i)
        if length > best_len:
            best_start, best_len = start, length

        start, length = expand(i, i + 1)
        if length > best_len:
            best_start, best_len = start, length

    return s[best_start:best_start + best_len]

import heapq

def dijkstra(grafo, origen):
    distancias = {origen: 0}
    cola = [(0, origen)]

    while cola:
        distancia_actual, nodo = heapq.heappop(cola)

        if distancia_actual > distancias.get(nodo, float("inf")):
            continue

        for vecino, peso in grafo.get(nodo, []):
            nueva_distancia = distancia_actual + peso

            if nueva_distancia < distancias.get(vecino, float("inf")):
                distancias[vecino] = nueva_distancia
                heapq.heappush(cola, (nueva_distancia, vecino))

    return distancias

def islas(matriz):
    if not matriz:
        return 0

    visitadas = set()
    total = 0

    for i, fila in enumerate(matriz):
        for j, valor in enumerate(fila):
            if valor == 1 and (i, j) not in visitadas:
                total += 1
                pila = [(i, j)]
                visitadas.add((i, j))

                while pila:
                    x, y = pila.pop()

                    for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        nx, ny = x + dx, y + dy

                        if (
                            0 <= nx < len(matriz)
                            and 0 <= ny < len(matriz[nx])
                            and (nx, ny) not in visitadas
                            and matriz[nx][ny] == 1
                        ):
                            visitadas.add((nx, ny))
                            pila.append((nx, ny))

    return total
